"""Task specializations refine expertise without granting additional permissions."""

from sabre.models import Task

SPECIALTIES = {
    "general": "Follow the project's established conventions and inspect the affected boundaries.",
    "backend": "Inspect API contracts, validation, authorization, transactions, concurrency, idempotency and error behavior as relevant to this task. Preserve compatibility and use focused contract or regression checks.",
    "frontend": "Inspect the user journey, semantic markup, keyboard use, responsive layout, loading, empty and failure states. Use the project's browser tests (for example Playwright) when available. For visible changes, request actual rendered evidence at relevant viewport sizes and inspect it with an authorized visual tool. A build or screenshot existence alone is not UX verification. If the required browser or visual evidence is unavailable, report that gap explicitly and do not claim visual approval.",
    "infrastructure": "Inspect existing infrastructure as code, runtime boundaries, network access, secrets, resource limits, health checks, persistence and recovery. Review the plan or diff and rollback before a material change. Do not apply cloud infrastructure or deploy: the factory delivers a branch and draft pull request.",
    "documentation": "Identify the reader and their task. Maintain the existing README, guides and API contracts where they belong; create a document only when it has a distinct maintenance purpose. Keep OpenAPI descriptions, examples, validation errors and generated client types consistent with implemented behavior. Generate types from the canonical schema rather than hand-editing them. Add a Mermaid or C4 diagram when it explains a material flow or trust boundary. Verify commands and examples; do not invent capabilities, version support, tests or production-readiness claims. Preserve legal notices and avoid redundant versions, progress diaries and autogenerated summaries.",
}

DESIGN_REVIEW = (
    "Identify backend, frontend and infrastructure responsibilities from repository evidence; they may share a repository or span separately authorized repositories. "
    "Do not assume every project contains all three or split services by default. Cite affected paths and contracts. "
    "For a design pattern, state the concrete pressure, the simpler alternative, benefits and costs. "
    "Separate verified facts from hypotheses and identify the source and applicable version for external recommendations. "
    "Never claim an exhaustive pattern catalog or a source lookup that did not occur. "
    "Review cohesion, dependency direction, duplication, testability and documentation usefulness within scope; do not introduce cosmetic rewrites or documents without a maintenance purpose."
)


def task_instruction(task: Task) -> str:
    if task.specialty == "general":
        # Preserve the checkpoint identity of tasks admitted before specialization existed.
        return f"Task: {task.title}"
    return f"Task: {task.title}\nTechnical specialty: {task.specialty}\n{SPECIALTIES[task.specialty]}"
